export type CampaignTerminalProps = {embedded?:boolean;legacyMode?:boolean;demoMode?:boolean;campaignId:number;me:{id:number;username:string};api:Api;onDirtyChange?:(dirty:boolean)=>void;onBusyChange?:(busy:boolean)=>void;requestedSection?:{section:Section;revision:number};onOpenSheet?:(request:SceneSheetRequest)=>void;sheetOpening?:boolean};
type Section = 'messages'|'places'|'assets'|'scene';
const SECTIONS:{id:Section;label:string;Icon:typeof Phone}[]=[{id:'messages',label:'Сообщения',Icon:MessageSquare},{id:'places',label:'Места',Icon:MapPin},{id:'assets',label:'Имущество',Icon:Building2},{id:'scene',label:'Поле боя',Icon:Crosshair}];
const STATUS = {submitted:'Ждём разрешения ГМ',approved:'Разрешено · можно бросать',resolved:'Результат подтверждён',rejected:'Отклонено'};
const KIND = {attack:'Атака',program:'Программа',other:'Другое'};
const TARGET_KIND = {person:'Человек',device:'Устройство',program:'Программа'};
const uid = () => {if(globalThis.crypto?.randomUUID)return globalThis.crypto.randomUUID();const bytes=new Uint8Array(16);if(globalThis.crypto?.getRandomValues)globalThis.crypto.getRandomValues(bytes);else for(let i=0;i<16;i++)bytes[i]=Math.floor(Math.random()*256);bytes[6]=(bytes[6]&15)|64;bytes[8]=(bytes[8]&63)|128;const hex=Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');return `${hex.slice(0,8)}-${hex.slice(8,12)}-${hex.slice(12,16)}-${hex.slice(16,20)}-${hex.slice(20)}`;};
const clone = <T,>(value:T):T => JSON.parse(JSON.stringify(value));
const edit = <T,>(value:T,existing=true):Editing<T> => ({value:clone(value),baseline:JSON.stringify(value),existing});
const canonical = (value:unknown):string => {const normalize=(v:any):any=>v&&typeof v==='object'?(Array.isArray(v)?v.map(normalize):Object.fromEntries(Object.keys(v).sort().map(k=>[k,normalize(v[k])]))):v;return JSON.stringify(normalize(value));};
