const changed = <T,>(draft:Editing<T>|null) => !!draft&&JSON.stringify(draft.value)!==draft.baseline;
const blankAction = ():ActionDraft=>({targetId:'',kind:'other',description:'',tool:'',roll:'',damage:''});
const errorText = (error:unknown) => error instanceof Error?error.message:'Не удалось выполнить действие.';
const timestamp = (raw:number) => new Date(raw<1e12?raw*1000:raw).toLocaleString('ru-RU',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});
