const amount = (n:number) => n.toLocaleString('ru-RU');

function RecipientPicker({characters,value,onChange,label='Кому доступно',disabled=false}:{characters:Character[];value:number[];onChange:(ids:number[])=>void;label?:string;disabled?:boolean}){
  return <fieldset className="terminal-recipients" disabled={disabled}><legend>{label}</legend><div className="terminal-recipient-tools"><button type="button" onClick={()=>onChange(characters.map(c=>c.id))}>Всем</button><button type="button" onClick={()=>onChange([])}>Никому</button></div><div>{characters.map(c=><label key={c.id}><input type="checkbox" checked={value.includes(c.id)} onChange={e=>onChange(e.target.checked?[...value,c.id]:value.filter(id=>id!==c.id))}/><span>{c.name}<small>{c.status==='reserve'?'Резерв':c.role}</small></span></label>)}</div>{!characters.length&&<p className="hint">Сначала прими персонажей в кампанию.</p>}</fieldset>;
}
function Info({children}:{children:React.ReactNode}){const settings=usePlayerSettings();return settings.hints?<details className="terminal-inline-help"><summary><CircleHelp aria-hidden="true"/>Как это работает</summary><p>{children}</p></details>:null;}
function Guide({section,gm}:{section:Section;gm:boolean}){
  const settings=usePlayerSettings();if(!settings.tutorial)return null;
  const texts:Record<Section,{title:string;body:string[]}>= {
    messages:{title:gm?'Выдай контакт и отправь сообщение':'Личный терминал персонажа',body:gm?['Создай контакт НПС и выбери персонажей, которые его знают. Пустой список оставляет контакт в папке ГМ. Заметки ведущего игрокам не передаются.','Открой контакт, выбери получателей и напиши от лица НПС. Каждый получатель получает отдельную переписку. Ответ игрока виден ведущему. Номер здесь вымышленный; приложение не отправляет SMS.']:['Выбери своего персонажа. Его контакты и переписки относятся только к этой кампании. Ведущий выдаёт знакомства и пишет от лица НПС.','Открой контакт, прочитай сообщение и ответь своим персонажем. Если связь пропала, текст останется на экране; его можно скачать.']},
    places:{title:'Адреса и доступные места',body:['Это схема расположения меток, а не каноничная карта Найт-Сити. Нажми метку или название, чтобы открыть адрес и описание.','Ведущий задаёт положение и решает, кому известно место. Пустой список получателей оставляет метку скрытой. Для своих персонажей можно переключать известные места.']},
    assets:{title:'Владение, доступ и хранилища',body:['Недвижимость и транспорт относятся к этой кампании. Владелец и те, кому разрешён доступ, видят карточку. Владение можно оставить общим без одного владельца.','Содержимое — запись вещей в квартире, гараже или багажнике. Она не переносит вещи из инвентаря автоматически. Цена и регулярные расходы — учётные поля: eb с листа сами не списываются.']},
    scene:{title:'Действия за столом через телефон',body:['ГМ готовит поле боя и открывает сцену. Нажми пешку противника, чтобы выбрать действие; свободную видимую клетку — чтобы запросить перемещение. ГМ рассматривает заявки под картой. Игрок описывает намерение и отправляет заявку от своего персонажа. Ведущий разрешает её с учётом ситуации.','Бросайте обычные кубики и вносите итог проверки и урон вручную. Здесь нет автоматического расчёта попадания, брони, Demon или сетевой доступности: их определяет правило и ведущий.','ГМ записывает результат и подтверждает его. Короткий эффект и общий журнал сопровождают описание за столом. После результата открой «Учесть последствия в листе»: внеси согласованные ранения и расходы, сохрани лист и вернись к той же сцене. Урон цели не переносится на действовавшего героя. Отмена результата не откатывает изменения листа.']}
  };
  return <details className="terminal-guide"><summary><BookOpen aria-hidden="true"/>{texts[section].title}</summary><div>{texts[section].body.map(text=><p key={text}>{text}</p>)}<small>Обучение и подсказки отключаются в настройках приложения.</small></div></details>;
}

