  const [busy,setBusy]=useState(false),[loading,setLoading]=useState(true),[connected,setConnected]=useState(false),[notice,setNotice]=useState<Notice|null>(null),[confirmation,setConfirmation]=useState<Confirmation|null>(null);
  const [effect,setEffect]=useState<string|null>(null),[lastRead,setLastRead]=useState<number|null>(null);
  const [readMarkers,setReadMarkers]=useState<Record<string,{id:string;created:number}>>({});
  const [vehicleCatalog,setVehicleCatalog]=useState<CatalogEntry[]|null>(null),[vehicleLoading,setVehicleLoading]=useState(false),[vehicleError,setVehicleError]=useState(''),[vehicleQuery,setVehicleQuery]=useState(''),[vehicleSelection,setVehicleSelection]=useState('');
  const generation=useRef(0),reads=useRef(0),reading=useRef(false),busyRef=useRef(false),alive=useRef(false);
